using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: Return the first element
    else if (n == 1) return b; // Base case: Return the second element
    else return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;
    bool validInput = false;

    while (!validInput) {
        cout << "Enter the first two Fibonacci numbers (separated by a space): ";
        if (cin >> start1 >> start2) {
