## C++ Bubble Sort with Memory Efficiency and JSON Handling (High Verbosity & Helpfulness)

Here's a C++ implementation of Bubble Sort optimized for memory efficiency, coupled with a demonstration of its integration into a job application system handling JSON data:

**1. In-Place Bubble Sort (Minimal Memory Overhead):**

```c++
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Using nlohmann/json for robust JSON handling

using json = nlohmann::json;
using namespace std;

void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            // Compare adjacent elements and swap if out of order (in-place)
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        n--; // Shrink the unsorted portion after each pass
    } while (swapped); 
}

int main() {
    // **JSON Input Simulation (Job Application Data)**
    string jsonData = R"({ "array": [5, 2, 9, 1, 5, 6] })";
    json jobApplicants = json::parse(jsonData);
    vector<int> applicantScores = jobApplicants["array"];

    cout << "Original Scores (JSON Input): ";
    for (int score : applicantScores) {
        cout << score << " ";
    }
    cout << endl;

    bubbleSort(applicantScores); 

    cout << "Sorted Scores (Ascending): ";
    for (int score : applicantScores) {
        cout << score << " ";
    }
    cout << endl;

    // **JSON Output (Modified Data Structure)**
    jobApplicants["sorted_scores"] = applicantScores; 
    cout << "\nUpdated JSON with Sorted Scores:\n" << jobApplicants.dump(4) << endl; 

    return 0;
}
```

