namespace GenericRestServiceWrapper
{
    public class RestServiceWrapper<T> where T : class
    {
        private readonly string _baseUrl;
        private readonly HttpClient _httpClient;
        private string _authToken;

        public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
        {
            _baseUrl = baseUrl;
            _httpClient = new HttpClient { BaseAddress = new Uri(baseUrl) };
            _authToken = initialAuthToken; // Store initial token
        }

        /// <summary>
        ///  Sets a new authentication token for subsequent requests.
        /// </summary>
        public void SetAuthToken(string token) => _authToken = token;

        /// <summary>
        ///  Generic GET request handler with auth token injection.
        /// </summary>
        public async Task<T> GetAsync(string relativeUrl, params KeyValuePair<string, string>[] queryParameters)
        {
            var uri = BuildUri(relativeUrl, queryParameters);
            return await MakeRequest<T>(HttpMethod.Get, uri);
        }

        /// <summary>
        ///  Generic POST request handler with auth token and payload handling.
        /// </summary>
        public async Task<T> PostAsync<TPayload>(string relativeUrl, TPayload data, params KeyValuePair<string, string>[] headers)
            where TPayload : class
        {
            var content = JsonConvert.SerializeObject(data);
            var requestHeaders = AddAuthTokenToHeaders(headers);
            var uri = BuildUri(relativeUrl);
            return await MakeRequest<T>(HttpMethod.Post, uri, content, requestHeaders);
