import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { User } from '@prisma/client';

const PERMISSIONS = [
  'READ_USERS', 'CREATE_USERS', 'UPDATE_USERS', 'DELETE_USERS',
  'READ_PRODUCTS', 'CREATE_PRODUCTS', 'UPDATE_PRODUCTS', 'DELETE_PRODUCTS',
  // Add more permissions...
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public route

    const request = context.switchToHttp().getRequest();
    const user: User = request.user;

    if (!user) throw new UnauthorizedException('User not authenticated');
    const userRoles = await this.prisma.user.findUnique({ where: { id: user.id } }).roles();

    return requiredRoles.every(role => userRoles.some(userRole => role === userRole));
  }
}

export const hasPermission = (...permissions: string[]) => (target, key, descriptor) => {
  Reflect.defineMetadata('roles', permissions, descriptor.value);
};
``` 


**Explanation (for understanding, NOT to be included in final `index.js`):**

1. **`PERMISSIONS` Array:**  Defines a centralized list of all available permission names within the application (extendable as needed).
2. **`RolesGuard`:**
   - Acts as a runtime authorization interceptor using NestJS decorators (`@Injectable`, `CanActivate`).
   - Retrieves required roles from function/route metadata (`@hasPermission` decorator).
   - Checks user authentication and compares retrieved user roles against required roles for access control. Throws `UnauthorizedException` if insufficient permissions.
3. **`hasPermission` Decorator:**
   - A metadata applicator. When placed on methods/routes, it stores an array of required permissions in the metadata for `RolesGuard` to use.
4. **Integration:** Developers

